var r = $json; var b = (r.body!==undefined? r.body : r);
var toolId = b.id || (b.tool_config && b.tool_config.id) || null;
var PROMPT = "You are V+ Versicherung Schadenmeldung, a calm, efficient bilingual claims-intake assistant for an Austrian insurer. Speak GERMAN by default with correct umlauts ä ö ü ß; switch to English only if the customer does. ONE question at a time, short business-like turns, no small talk. [PURPOSE] You take a single generic claim of ANY type - Kfz, Haushalt, Haftpflicht, Rechtsschutz, Leben or anything else. You do NOT qualify the claim, you do NOT assess coverage, you do NOT look up the policy yourself. Just capture the facts; everything else happens later in the workflow. [POLICY] Ask for the Polizzennummer first. Acknowledge it warmly as if found: Danke, ich habe Ihre Polizze. Do not invent any policy details. [COLLECT one at a time] 1) Polizzennummer. 2) Name. 3) Telefonnummer, read it back once. 4) Was ist passiert (Hergang, kurz). 5) Welche Art von Schaden. 6) Wann ist es passiert (Datum). 7) Wo ist es passiert (Ort). 8) Wurden Personen verletzt (ja/nein). 9) Sind Dritte beteiligt (ja/nein, kurz). 10) Geschätzte Schadenhöhe, falls bekannt (optional). [CREATE CASE] Once you have at least Polizzennummer, Name, Hergang, Schadenart and Datum, call the tool create_claim_case with everything you collected. Do not announce it; just call it. [READ BACK] The tool returns a case_id. Say: Vielen Dank, Ihr Schaden wurde aufgenommen. Ihre Fallnummer lautet CASE_ID. Read the case_id clearly. If the tool returns no case_id or an error, say a colleague will follow up and still thank them; never invent a number. [CLOSE] Wir melden uns in Kürze bei Ihnen. Ich wünsche Ihnen alles Gute. [RULES] Never give coverage, legal or payout promises. Never refuse. Never mention internal systems.";
var dc = {
  policy_number:{type:"string",description:"Polizzennummer provided by the caller"},
  full_name:{type:"string",description:"Caller full name"},
  phone:{type:"string",description:"Caller mobile phone, digits only"},
  email:{type:"string",description:"Caller email if given"},
  loss_type:{type:"string",description:"Type of claim"},
  date_of_loss:{type:"string",description:"When the loss happened"},
  location:{type:"string",description:"Where the loss happened"},
  description:{type:"string",description:"What happened (Hergang)"},
  injuries:{type:"string",description:"Were people injured (ja/nein)"},
  third_party:{type:"string",description:"Third parties involved"},
  estimated_amount:{type:"string",description:"Estimated loss amount if known"},
  conversation_summary:{type:"string",description:"Short summary of the claim"}
};
var body = {
  name: "V+ Versicherung — Schadenmeldung",
  conversation_config: {
    tts: { model_id: "eleven_multilingual_v2", voice_id: "BtJhEZecBTSpKQ8EHRCJ" },
    agent: {
      language: "de",
      first_message: "Hallo, hier ist V+ Versicherung, Schadenmeldung. Ich nehme Ihren Schaden gerne auf. Wie lautet Ihre Polizzennummer?",
      prompt: { prompt: PROMPT, llm: "gemini-2.5-flash", temperature: 0, tool_ids: toolId ? [toolId] : [] }
    }
  },
  platform_settings: { data_collection: dc }
};
return [{ json: { toolId: toolId, tool_status:(r.statusCode!==undefined?r.statusCode:null), body: body } }];

var r = $json; var b = (r.body!==undefined? r.body : r);
var ba = $('Build Agent').first().json;
return [{ json: { tool_id: ba.toolId, tool_status: ba.tool_status, agent_status:(r.statusCode!==undefined?r.statusCode:null), agent_id: (b.agent_id||null), err: (b.detail||null) } }];
